// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 ts, uint256 bn) public {
        // keep values in realistic, admissible ranges; wide enough that
        // block.number != block.timestamp for almost all inputs
        ts = bound(ts, 1, type(uint48).max);
        bn = bound(bn, 1, type(uint64).max);
        vm.warp(ts);
        vm.roll(bn);

        address actor = makeAddr("actor");
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        // fallback cannot be called by name; use a low-level call
        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok);

        // General rule: after any successful fallback, pastBlockTime() equals block.timestamp.
        assertTrue(c.pastBlockTime() == ts);
    }
}
